    return ResponseEntity.ok(notificationService.toDto(notification));
}

@PostMapping("/notifications")
public ResponseEntity<NotificationDto> createNotification(@RequestBody @Valid NotificationRequest request) {
    Notification created = notificationService.createNotification(request.toNotification());
    return ResponseEntity.status(HttpStatus.CREATED).body(notificationService.toDto(created));
}

@Override
public boolean equals(Object o) {
    if (this == o) return true;
    if (!(o instanceof Notification)) return false;
    Notification other = (Notification) o;
    return Objects.equals(this.id, other.id);
}

@Override
public int hashCode() {
    return Objects.hash(id);
}

public NotificationBuilder withId(String id) {
    this.id = id;
    return this;
}

public void validateNotification(Notification notification) {
    if (notification.getId() == null || notification.getId().isBlank()) {
        throw new IllegalArgumentException("id must not be blank");
    }
}

public List<Notification> searchNotificationsById(String query) {
    return notificationRepository.findByIdContainingIgnoreCase(query);
}

public Category getCategoryById(Long id) {
    return categoryRepository.findById(id)
        .orElseThrow(() -> new CategoryNotFoundException("No category with id " + id));
}

@Transactional
public Category createCategory(Category category) {
    category.setCreatedAt(Instant.now());
    return categoryRepository.save(category);
}

@Transactional
public void deleteCategory(Long id) {
    if (!categoryRepository.existsById(id)) {
        throw new CategoryNotFoundException("No category with id " + id);
    }
    categoryRepository.deleteById(id);
}

public List<Category> findActiveCategorys() {
    return categoryRepository.findAll().stream()
        .filter(Category::isActive)
        .collect(Collectors.toList());
}

public CategoryDto toDto(Category category) {
    CategoryDto dto = new CategoryDto();
    dto.setId(category.getId());
    dto.setName(category.getName());
    return dto;
}

@GetMapping("/categorys/{id}")
public ResponseEntity<CategoryDto> getCategory(@PathVariable Long id) {
    Category category = categoryService.getCategoryById(id);
    return ResponseEntity.ok(categoryService.toDto(category));
}

@PostMapping("/categorys")
public ResponseEntity<CategoryDto> createCategory(@RequestBody @Valid CategoryRequest request) {
    Category created = categoryService.createCategory(request.toCategory());
    return ResponseEntity.status(HttpStatus.CREATED).body(categoryService.toDto(created));
}
